#include <vector>
#include <unordered_map>

using namespace std;

class Solution {
public:
    int numberOfBoomerangs(vector<vector<int>>& points) {
        int res = 0;
        for (auto& p : points) {
            unordered_map<int, int> count;
            for (auto& q : points) {
                int dx = p[0] - q[0], dy = p[1] - q[1];
                count[dx * dx + dy * dy]++;
            }
            for (auto& [_, v] : count)
                res += v * (v - 1);
        }
        return res;
    }
};
